package com.bananalab.lite;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.net.Uri;import android.media.*;import java.io.*;import java.util.*;import org.json.*;
/** Actual persistent engine, atomic tasks and Android image/video exports. */
public final class Stage36Instrumentation extends Instrumentation{
 void check(boolean b,String why){if(!b)throw new AssertionError(why);}void note(String s){Bundle b=new Bundle();b.putString("stream",s+"\n");sendStatus(0,b);}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{Context c=getTargetContext();Semilla m=OwnBrain.load(c);List<String[]> history=new ArrayList<>();BananaEngine.Result r=BananaEngine.run(c,"crea a Tony una banana detective con sobretodo; agrega un gato llamado Milo; Tony habla con Milo mientras entra el tomate",history,"",true,m);check(r.scene.cast.size()==3&&r.scene.actions.size()==3,"compound create and execute");String id=r.scene.get("banana").designId,before=BananaProject.current(c).json().toString();BananaEngine.Result bad=BananaEngine.run(c,"pone el fondo en la playa; destrui el universo",history,"",true,m);check(!bad.changed&&before.equals(BananaProject.current(c).json().toString()),"atomic rollback persistent");
 r=BananaEngine.run(c,"deja todo igual pero cambia al que entro por un conejo y hacelo mas alto",history,"",true,m);check(r.scene.get("tomate").kind.equals("conejo")&&r.scene.get("tomate").look.contains("alto")&&id.equals(r.scene.get("banana").designId),"grounded replace preserves Tony");check(CreatorMemory.load(c).lastTask.contains("2 pasos"),"receipt survives reload");
 BananaEngine.run(c,"recorda que Tony vive en el bosque",history,"",true,m);BananaEngine.run(c,"recorda que Milo es detective",history,"",true,m);BananaEngine.run(c,"corregí el recuerdo 1: Tony vive en la playa",history,"",true,m);BananaEngine.run(c,"olvida el recuerdo 2",history,"",true,m);check(ProjectMemory.reply(c,"mis recuerdos").contains("playa")&&!ProjectMemory.reply(c,"mis recuerdos").contains("Milo"),"persisted memory correction deletion");check(BananaEngine.run(c,"resumi mi proyecto",history,"",true,m).text.contains("conejo"),"grounded summary");
 SceneDraft finalScene=r.scene.copy();finalScene.sound=true;finalScene.lighting="day";finalScene.fog=0;File dir=c.getExternalFilesDir(null);VideoExporter.Monitor monitor=new VideoExporter.Monitor(){public boolean cancelled(){return false;}public void progress(int f,int n){}};JSONObject png=BananaExporter.request(c,"png",finalScene).put("time",.95);File image=new File(dir,"stage36.png");BananaExporter.write(c,png,Uri.fromFile(image),monitor);Bitmap b=BitmapFactory.decodeFile(image.getAbsolutePath());check(b!=null&&b.getWidth()==384,"PNG export");b.recycle();note("PNG_3_ACTORS_OK");File video=new File(dir,"stage36.mp4");BananaExporter.write(c,BananaExporter.request(c,"mp4",finalScene),Uri.fromFile(video),monitor);MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(video.getAbsolutePath());check(extractor.getTrackCount()==2,"audio video tracks");}finally{extractor.release();}note("MP4_AV_OK");result.putString("stream","PASS STAGE36 persisted compound scene, rollback, grounded replacement, memory CRUD, receipt, PNG and MP4 AV.\n");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));result.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,result);}}
}
